package com.ellenco.platform.domain;import jakarta.persistence.*;import java.time.LocalDateTime;
@Entity @Table(name="ferramenta_emprestimos")public class ToolLoan{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(optional=false)@JoinColumn(name="ferramenta_id")private ToolAsset ferramenta;private String responsavelNome;private String responsavelCpf;private String obra;private String frenteServico;private LocalDateTime emprestadoEm=LocalDateTime.now();private LocalDateTime devolucaoPrevista;private LocalDateTime devolvidoEm;private String estadoSaida;private String estadoDevolucao;private String status="EMPRESTADO";private String observacoes;private String comprovanteCodigo;public Long getId(){return id;}public ToolAsset getFerramenta(){return ferramenta;}public void setFerramenta(ToolAsset v){ferramenta=v;}public String getResponsavelNome(){return responsavelNome;}public void setResponsavelNome(String v){responsavelNome=v;}public String getResponsavelCpf(){return responsavelCpf;}public void setResponsavelCpf(String v){responsavelCpf=v;}public String getObra(){return obra;}public void setObra(String v){obra=v;}public String getFrenteServico(){return frenteServico;}public void setFrenteServico(String v){frenteServico=v;}public LocalDateTime getEmprestadoEm(){return emprestadoEm;}public LocalDateTime getDevolucaoPrevista(){return devolucaoPrevista;}public void setDevolucaoPrevista(LocalDateTime v){devolucaoPrevista=v;}public LocalDateTime getDevolvidoEm(){return devolvidoEm;}public void setDevolvidoEm(LocalDateTime v){devolvidoEm=v;}public String getEstadoSaida(){return estadoSaida;}public void setEstadoSaida(String v){estadoSaida=v;}public String getEstadoDevolucao(){return estadoDevolucao;}public void setEstadoDevolucao(String v){estadoDevolucao=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public String getObservacoes(){return observacoes;}public void setObservacoes(String v){observacoes=v;}public String getComprovanteCodigo(){return comprovanteCodigo;}public void setComprovanteCodigo(String v){comprovanteCodigo=v;}public boolean isAtrasado(){return "EMPRESTADO".equals(status)&&devolucaoPrevista!=null&&devolucaoPrevista.isBefore(LocalDateTime.now());}}
